import { Component, ChangeDetectionStrategy, OnInit, inject, signal, viewChild } from '@angular/core';
import { Router } from '@angular/router';
import { BackofficeService } from '../../../../core/services/backoffice.service';
import { DocumentoIndexado, ToastMessage } from '../../../../core/models/backoffice.model';
import { AdminNavbarComponent } from '../../components/admin-navbar/admin-navbar.component';
import { AdminStatsComponent } from '../../components/admin-stats/admin-stats.component';
import { DocumentTableComponent } from '../../components/document-table/document-table.component';
import { DocumentUploadModalComponent } from '../../components/document-upload-modal/document-upload-modal.component';
import { ConfirmDeleteModalComponent } from '../../components/confirm-delete-modal/confirm-delete-modal.component';

@Component({
  selector: 'app-admin-dashboard',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [
    AdminNavbarComponent,
    AdminStatsComponent,
    DocumentTableComponent,
    DocumentUploadModalComponent,
    ConfirmDeleteModalComponent
  ],
  templateUrl: './admin-dashboard.component.html',
  styleUrl: './admin-dashboard.component.css'
})
export class AdminDashboardComponent implements OnInit {
  private readonly backofficeService = inject(BackofficeService);
  private readonly router = inject(Router);

  private readonly uploadModal = viewChild<DocumentUploadModalComponent>('uploadModal');

  readonly session = this.backofficeService.currentSession;

  readonly documentos = signal<DocumentoIndexado[]>([]);
  readonly totalDocumentos = signal<number>(0);
  readonly totalFragmentos = signal<number>(0);

  readonly isLoadingList = signal<boolean>(false);
  readonly isUploadModalOpen = signal<boolean>(false);
  readonly isUploading = signal<boolean>(false);

  readonly docToDelete = signal<DocumentoIndexado | null>(null);
  readonly deletingId = signal<string | null>(null);

  readonly toasts = signal<ToastMessage[]>([]);

  ngOnInit(): void {
    this.cargarDocumentos();
  }

  cargarDocumentos(): void {
    this.isLoadingList.set(true);
    this.backofficeService.listarDocumentos().subscribe({
      next: (res) => {
        this.documentos.set(res.documentos || []);
        this.totalDocumentos.set(res.total_documentos ?? res.documentos.length);
        this.totalFragmentos.set(res.total_fragmentos ?? 0);
        this.isLoadingList.set(false);
      },
      error: (err) => {
        this.isLoadingList.set(false);
        this.showToast('error', 'Error al cargar documentos', err.message);
      }
    });
  }

  openUploadModal(): void {
    this.isUploadModalOpen.set(true);
  }

  closeUploadModal(): void {
    this.isUploadModalOpen.set(false);
  }

  onUploadDocument(payload: {
    archivo: File;
    documentoId: string;
    fuente: string;
    areaOrigen: string;
    clasificacionSensibilidad: string;
  }): void {
    this.isUploading.set(true);

    this.backofficeService.indexarDocumento(payload).subscribe({
      next: (res) => {
        this.isUploading.set(false);
        this.isUploadModalOpen.set(false);
        this.uploadModal()?.resetForm();
        this.showToast(
          'success',
          'Documento indexado con éxito',
          `Se guardaron ${res.fragmentos_indexados} fragmentos vectoriales para "${payload.fuente}".`
        );
        this.cargarDocumentos();
      },
      error: (err) => {
        this.isUploading.set(false);
        this.showToast('error', 'Error en la ingesta', err.message);
      }
    });
  }

  onRequestDelete(doc: DocumentoIndexado): void {
    this.docToDelete.set(doc);
  }

  onCancelDelete(): void {
    if (this.deletingId()) return;
    this.docToDelete.set(null);
  }

  onConfirmDelete(documentoId: string): void {
    this.deletingId.set(documentoId);
    const fuenteName = this.docToDelete()?.fuente || documentoId;

    this.backofficeService.eliminarDocumento(documentoId).subscribe({
      next: () => {
        this.deletingId.set(null);
        this.docToDelete.set(null);
        this.showToast(
          'info',
          'Documento eliminado',
          `Se eliminó "${fuenteName}" y todos sus vectores de PostgreSQL.`
        );
        this.cargarDocumentos();
      },
      error: (err) => {
        this.deletingId.set(null);
        this.docToDelete.set(null);
        this.showToast('error', 'No se pudo eliminar', err.message);
      }
    });
  }

  onLogout(): void {
    this.backofficeService.logout();
    this.router.navigate(['/backoffice/login']);
  }

  showToast(type: 'success' | 'error' | 'info', title: string, message: string): void {
    const id = 'toast_' + Date.now();
    this.toasts.update((list) => [...list, { id, type, title, message }]);
    setTimeout(() => {
      this.dismissToast(id);
    }, 5000);
  }

  dismissToast(id: string): void {
    this.toasts.update((list) => list.filter((t) => t.id !== id));
  }
}
