import { Component, ChangeDetectionStrategy, input, output, signal, computed } from '@angular/core';
import { DatePipe } from '@angular/common';
import { DocumentoIndexado } from '../../../../core/models/backoffice.model';

@Component({
  selector: 'app-document-table',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [DatePipe],
  templateUrl: './document-table.component.html',
  styleUrl: './document-table.component.css'
})
export class DocumentTableComponent {
  readonly documentos = input.required<DocumentoIndexado[]>();
  readonly isLoading = input<boolean>(false);
  readonly deletingId = input<string | null>(null);

  readonly requestDelete = output<DocumentoIndexado>();
  readonly openUpload = output<void>();

  // Filtros reactivos
  readonly searchQuery = signal<string>('');
  readonly selectedArea = signal<string>('TODOS');
  readonly pageSize = signal<number>(10);
  readonly currentPage = signal<number>(1);

  readonly areasDisponibles = computed(() => {
    const areas = new Set<string>(['GENERAL', 'ADMISIONES', 'SECRETARIA', 'DIRECCION', 'TESORERIA']);
    for (const d of this.documentos()) {
      if (d.area_origen) {
        areas.add(d.area_origen.toUpperCase());
      }
    }
    return ['TODOS', ...Array.from(areas)];
  });

  // Documentos filtrados por texto y área
  readonly filteredDocuments = computed(() => {
    const query = this.searchQuery().trim().toLowerCase();
    const area = this.selectedArea();

    return this.documentos().filter((doc) => {
      const matchesArea = area === 'TODOS' || doc.area_origen?.toUpperCase() === area;
      const matchesQuery =
        !query ||
        doc.documento_id.toLowerCase().includes(query) ||
        doc.fuente.toLowerCase().includes(query) ||
        doc.area_origen.toLowerCase().includes(query);

      return matchesArea && matchesQuery;
    });
  });

  // Total de páginas
  readonly totalPages = computed(() => {
    const total = this.filteredDocuments().length;
    return Math.max(1, Math.ceil(total / this.pageSize()));
  });

  // Documentos de la página actual
  readonly paginatedDocuments = computed(() => {
    const page = Math.min(this.currentPage(), this.totalPages());
    const size = this.pageSize();
    const start = (page - 1) * size;
    return this.filteredDocuments().slice(start, start + size);
  });

  readonly startIndex = computed(() => {
    if (this.filteredDocuments().length === 0) return 0;
    const page = Math.min(this.currentPage(), this.totalPages());
    return (page - 1) * this.pageSize() + 1;
  });

  readonly endIndex = computed(() => {
    const total = this.filteredDocuments().length;
    if (total === 0) return 0;
    const page = Math.min(this.currentPage(), this.totalPages());
    return Math.min(page * this.pageSize(), total);
  });

  readonly pageNumbers = computed(() => {
    const total = this.totalPages();
    return Array.from({ length: total }, (_, i) => i + 1);
  });

  onSearchChange(event: Event): void {
    const value = (event.target as HTMLInputElement).value;
    this.searchQuery.set(value);
    this.currentPage.set(1);
  }

  onAreaChange(event: Event): void {
    const value = (event.target as HTMLSelectElement).value;
    this.selectedArea.set(value);
    this.currentPage.set(1);
  }

  onPageSizeChange(event: Event): void {
    const value = Number((event.target as HTMLSelectElement).value);
    this.pageSize.set(value);
    this.currentPage.set(1);
  }

  clearFilters(): void {
    this.searchQuery.set('');
    this.selectedArea.set('TODOS');
    this.currentPage.set(1);
  }

  goToPage(page: number): void {
    if (page >= 1 && page <= this.totalPages()) {
      this.currentPage.set(page);
    }
  }
}
