import { Component, ChangeDetectionStrategy, input, output, signal, effect } from '@angular/core';

@Component({
  selector: 'app-document-upload-modal',
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './document-upload-modal.component.html',
  styleUrl: './document-upload-modal.component.css'
})
export class DocumentUploadModalComponent {
  readonly isOpen = input<boolean>(false);
  readonly isUploading = input<boolean>(false);
  readonly defaultArea = input<string>('GENERAL');

  readonly close = output<void>();
  readonly upload = output<{
    archivo: File;
    documentoId: string;
    fuente: string;
    areaOrigen: string;
    clasificacionSensibilidad: string;
  }>();

  readonly selectedFile = signal<File | null>(null);
  readonly documentoId = signal<string>('');
  readonly fuente = signal<string>('');
  readonly areaOrigen = signal<string>('GENERAL');
  readonly clasificacionSensibilidad = signal<string>('publico');
  readonly isDragging = signal<boolean>(false);
  readonly validationError = signal<string | null>(null);
  readonly uploadStep = signal<number>(1);

  private stepInterval: ReturnType<typeof setInterval> | null = null;

  constructor() {
    effect(() => {
      if (this.isOpen()) {
        this.areaOrigen.set(this.defaultArea() || 'GENERAL');
      }
    });

    effect(() => {
      if (this.isUploading()) {
        this.startProgressSimulation();
      } else {
        this.stopProgressSimulation();
      }
    });
  }

  onDragOver(event: DragEvent): void {
    event.preventDefault();
    event.stopPropagation();
    if (!this.isUploading()) {
      this.isDragging.set(true);
    }
  }

  onDragLeave(event: DragEvent): void {
    event.preventDefault();
    event.stopPropagation();
    this.isDragging.set(false);
  }

  onDrop(event: DragEvent): void {
    event.preventDefault();
    event.stopPropagation();
    this.isDragging.set(false);
    if (this.isUploading()) return;

    const files = event.dataTransfer?.files;
    if (files && files.length > 0) {
      this.handleFileSelection(files[0]);
    }
  }

  onFileSelected(event: Event): void {
    const input = event.target as HTMLInputElement;
    if (input.files && input.files.length > 0) {
      this.handleFileSelection(input.files[0]);
    }
  }

  private handleFileSelection(file: File): void {
    this.validationError.set(null);

    const allowedExtensions = ['.pdf', '.docx', '.pptx', '.txt', '.md', '.csv'];
    const lowerName = file.name.toLowerCase();
    const isValidExt = allowedExtensions.some((ext) => lowerName.endsWith(ext));

    if (!isValidExt) {
      this.validationError.set('Formato no permitido. Sube archivos .pdf, .docx, .pptx, .txt, .md o .csv');
      return;
    }

    const maxBytes = 25 * 1024 * 1024;
    if (file.size > maxBytes) {
      this.validationError.set('El archivo supera el límite máximo permitido de 25 MB.');
      return;
    }

    this.selectedFile.set(file);

    // Autocompletar Fuente e ID sugerido si están vacíos
    const baseName = file.name.replace(/\.[^/.]+$/, '');
    if (!this.fuente().trim()) {
      this.fuente.set(baseName.replace(/[-_]/g, ' '));
    }
    if (!this.documentoId().trim()) {
      const slug = baseName
        .toLowerCase()
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .replace(/[^a-z0-9]+/g, '_')
        .replace(/^_|_$/g, '')
        .slice(0, 24);
      const dateSuffix = new Date().toISOString().slice(0, 10).replace(/-/g, '');
      this.documentoId.set(`doc_${slug}_${dateSuffix}`);
    }
  }

  removeFile(): void {
    if (this.isUploading()) return;
    this.selectedFile.set(null);
    this.validationError.set(null);
  }

  onDocumentoIdInput(event: Event): void {
    this.documentoId.set((event.target as HTMLInputElement).value);
  }

  onFuenteInput(event: Event): void {
    this.fuente.set((event.target as HTMLInputElement).value);
  }

  onAreaChange(event: Event): void {
    this.areaOrigen.set((event.target as HTMLSelectElement).value);
  }

  onSensibilidadChange(event: Event): void {
    this.clasificacionSensibilidad.set((event.target as HTMLSelectElement).value);
  }

  formatFileSize(bytes: number): string {
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(2)} MB`;
  }

  canSubmit(): boolean {
    return (
      !!this.selectedFile() &&
      this.documentoId().trim().length > 0 &&
      this.fuente().trim().length > 0 &&
      !this.isUploading()
    );
  }

  onSubmit(event: Event): void {
    event.preventDefault();
    const file = this.selectedFile();
    if (!file || !this.canSubmit()) return;

    this.upload.emit({
      archivo: file,
      documentoId: this.documentoId().trim(),
      fuente: this.fuente().trim(),
      areaOrigen: this.areaOrigen(),
      clasificacionSensibilidad: this.clasificacionSensibilidad()
    });
  }

  onClose(): void {
    if (this.isUploading()) return;
    this.resetForm();
    this.close.emit();
  }

  resetForm(): void {
    this.selectedFile.set(null);
    this.documentoId.set('');
    this.fuente.set('');
    this.validationError.set(null);
    this.uploadStep.set(1);
  }

  private startProgressSimulation(): void {
    this.uploadStep.set(1);
    this.stopProgressSimulation();
    this.stepInterval = setInterval(() => {
      this.uploadStep.update((step) => (step < 3 ? step + 1 : 3));
    }, 1800);
  }

  private stopProgressSimulation(): void {
    if (this.stepInterval) {
      clearInterval(this.stepInterval);
      this.stepInterval = null;
    }
  }
}
