import { Component, ChangeDetectionStrategy, input, output } from '@angular/core';
import { DocumentoIndexado } from '../../../../core/models/backoffice.model';

@Component({
  selector: 'app-confirm-delete-modal',
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './confirm-delete-modal.component.html',
  styleUrl: './confirm-delete-modal.component.css'
})
export class ConfirmDeleteModalComponent {
  readonly documento = input<DocumentoIndexado | null>(null);
  readonly isDeleting = input<boolean>(false);

  readonly cancel = output<void>();
  readonly confirm = output<string>();

  onConfirm(): void {
    const doc = this.documento();
    if (doc && !this.isDeleting()) {
      this.confirm.emit(doc.documento_id);
    }
  }
}
